// Liberation Sans — the metric-compatible, open-licensed (SIL OFL) stand-in for
// Arial, subset to Latin-1 + common punctuation and base64-embedded for jsPDF.
// macOS/Windows "Arial" is proprietary (Monotype) and cannot be redistributed,
// so Liberation Sans is the correct font to ship. Registered under the family
// name "Arial" via registerArialFont() so generators call setFont('Arial', ...).
//
// Source: liberation-fonts 2.1.5, subset with pyftsubset to ~16KB/style.
// Regenerate: see scripts/build-pdf-arial-font (documented in the PR).
/* eslint-disable */

export const ARIAL_REGULAR_B64 = '';
export const ARIAL_BOLD_B64 = '';
export const ARIAL_ITALIC_B64 = '';
